11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	import org.springframework.security.access.prepost.PreAuthorize;
14	import org.springframework.web.bind.annotation.CrossOrigin;
15	import org.springframework.web.bind.annotation.RestController;
16	import org.springframework.web.bind.annotation.RequestMapping;
17	
18	@RestController
19	@CrossOrigin(exposedHeaders = "errors, content-type")
20	@RequestMapping("/api")
21	public class OwnerRestControllerV2 implements OwnerV2Api {
22	
23	    private final ClinicService clinicService;
24	    private final OwnerMapper ownerMapper;
25	
26	    public OwnerRestControllerV2(ClinicService clinicService, OwnerMapper ownerMapper) {
27	        this.clinicService = clinicService;
28	        this.ownerMapper = ownerMapper;
29	    }
30	
31	    @Override
32	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
33	    public ResponseEntity<OwnerPageDto> listOwnersPage(String lastName, Integer page, Integer size) {
34	        int pageNumber = page == null ? 0 : page;
35	        int pageSize = size == null ? 20 : size;
36	        Page<Owner> owners = this.clinicService.findOwners(
37	            lastName,
38	            PageRequest.of(pageNumber, pageSize, Sort.by("id")));
39	        return new ResponseEntity<>(ownerMapper.toOwnerPageDto(owners), HttpStatus.OK);
40	    }
41	}
