16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDay;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "postcode")
62	    private String postcode;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    public LocalDate getBirthDate() {
68	        return this.birthDate;
69	    }
70	
71	    public void setBirthDate(LocalDate birthDate) {
72	        this.birthDate = birthDate;
73	    }
74	
75	    public String getCustomerCode() {
76	        return this.customerCode;
77	    }
78	
79	    public void setCustomerCode(String customerCode) {
80	        this.customerCode = customerCode;
81	    }
82	
83	    public String getPostcode() {
84	        return this.postcode;
85	    }
86	
87	    public void setPostcode(String postcode) {
88	        this.postcode = postcode;
89	    }
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    public LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    /** Set the registration date, defaulting to the server's current date when none is supplied. */
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = BusinessDay.onOrNextBusinessDay(
101	            registrationDate == null ? LocalDate.now() : registrationDate);
102	    }
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email == null ? null : email.toLowerCase();
110	    }
111	
112	    public String getAddress() {
113	        return this.address;
114	    }
115	
116	    public void setAddress(String address) {
117	        this.address = address;
118	    }
119	
120	    public String getCity() {
121	        return this.city;
122	    }
123	
124	    public void setCity(String city) {
125	        this.city = city;
126	    }
127	
128	    public String getTelephone() {
129	        return this.telephone;
130	    }
131	
132	    public void setTelephone(String telephone) {
133	        this.telephone = telephone;
134	    }
135	
136	    protected Set<Pet> getPetsInternal() {
137	        if (this.pets == null) {
138	            this.pets = new HashSet<>();
139	        }
140	        return this.pets;
141	    }
142	
143	    protected void setPetsInternal(Set<Pet> pets) {
144	        this.pets = pets;
145	    }
146	
147	    public List<Pet> getPets() {
148	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
149	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
150	        return Collections.unmodifiableList(sortedPets);
151	    }
152	
153	    public void setPets(List<Pet> pets) {
154	        this.pets = new HashSet<>(pets);
155	    }
156	
157	    public void addPet(Pet pet) {
158	        getPetsInternal().add(pet);
159	        pet.setOwner(this);
160	    }
161	
162	    /**
163	     * Return the Pet with the given name, or null if none found for this Owner.
164	     *
165	     * @param name to test
166	     * @return true if pet name is already in use
167	     */
168	    public Pet getPet(String name) {
169	        return getPet(name, false);
170	    }
171	
172	    /**
173	     * Return the Pet with the given name, or null if none found for this Owner.
174	     *
175	     * @param name to test
176	     * @return true if pet name is already in use
177	     */
178	    public Pet getPet(String name, boolean ignoreNew) {
179	        name = name.toLowerCase();
180	        for (Pet pet : getPetsInternal()) {
181	            if (!ignoreNew || !pet.isNew()) {
182	                String compName = pet.getName();
183	                compName = compName.toLowerCase();
184	                if (compName.equals(name)) {
185	                    return pet;
186	                }
187	            }
188	        }
189	        return null;
190	    }
191	
192	    public Pet getPet(Integer petId) {
193	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
194	    }
195	
196	    @Override
197	    public String toString() {
198	        return new ToStringCreator(this)
199	
200	            .append("id", this.getId())
201	            .append("new", this.isNew())
202	            .append("lastName", this.getLastName())
203	            .append("firstName", this.getFirstName())
204	            .append("address", this.address)
205	            .append("city", this.city)
206	            .append("telephone", this.telephone)
207	            .toString();
208	    }
209	}
