3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	import java.util.Map;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Builds an owner's {@code customerCode} in the format {@code '<REGION>-<HASH8>'}: the region code
13	 * derived from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, then the fixed city
14	 * fallback, else {@code UNKNOWN}) and the first eight upper-case hex characters of SHA-256 over the
15	 * normalized telephone concatenated with the last name. No sequence numbers are used.
16	 */
17	final class CustomerCode {
18	
19	    /** Fixed city-to-region fallback, used only when the postcode identifies no region. */
20	    private static final Map<String, String> CITY_REGION =
21	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    private CustomerCode() {
24	    }
25	
26	    static String of(Owner owner, Collection<Owner> existing) {
27	        return region(owner) + "-" + hash8(owner.getTelephone() + owner.getLastName());
28	    }
29	
30	    private static String region(Owner owner) {
31	        String postcode = owner.getPostcode();
32	        String byPostcode = postcode == null || !postcode.matches("[0-9]{4}") ? null
33	            : switch (Integer.parseInt(postcode) / 100) {
34	                case 20 -> "NSW";
35	                case 30 -> "VIC";
36	                case 40 -> "QLD";
37	                default -> null;
38	            };
39	        return byPostcode != null ? byPostcode : CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
40	    }
41	
42	    private static String hash8(String value) {
43	        StringBuilder sb = new StringBuilder();
44	        for (byte b : sha256(value)) {
45	            sb.append(String.format("%02X", b));
46	        }
47	        return sb.substring(0, 8);
48	    }
49	
50	    private static byte[] sha256(String value) {
51	        try {
52	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
53	        } catch (NoSuchAlgorithmException e) {
54	            throw new IllegalStateException(e);
55	        }
56	    }
57	}
