61	        ownerDto.setLocality(dash > 0 ? code.substring(0, dash)
62	            : LocalityResolver.resolve(owner.getCity(), owner.getPostcode()));
63	    }
64	
65	    /**
66	     * Derives 'contactPreference' for the response: 'EMAIL' when the owner has an email address,
67	     * otherwise 'PHONE'. Non-persistent, so it never affects storage or the request payload.
68	     */
69	    @AfterMapping
70	    default void deriveContactPreference(Owner owner, @MappingTarget OwnerDto ownerDto) {
71	        String email = owner.getEmail();
72	        ownerDto.setContactPreference(email == null || email.isBlank() ? "PHONE" : "EMAIL");
73	    }
74	
75	    /**
76	     * Derives 'ageBand' for the response from the owner's birth date, measured against the
77	     * registration date: 'MINOR' when under 18, 'ADULT' for 18-64 and 'SENIOR' for 65+. Left
78	     * unset when no birth date is supplied. Non-persistent, so it never affects storage.
79	     */
80	    @AfterMapping
81	    default void deriveAgeBand(Owner owner, @MappingTarget OwnerDto ownerDto) {
82	        java.time.LocalDate birthDate = owner.getBirthDate();
83	        if (birthDate == null) {
84	            return;
85	        }
86	        int years = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
87	        ownerDto.setAgeBand(years < 18 ? "MINOR" : years < 65 ? "ADULT" : "SENIOR");
88	    }
89	
90	    /**
91	     * Derives 'telephoneDisplay' for the response: the stored E.164 'telephone' formatted for
92	     * humans by {@link org.springframework.samples.petclinic.util.TelephoneDisplay#format}. Raw
93	     * 'telephone' is left untouched. Non-persistent, so it never affects storage or the request payload.
94	     */
95	    @AfterMapping
96	    default void deriveTelephoneDisplay(Owner owner, @MappingTarget OwnerDto ownerDto) {
97	        ownerDto.setTelephoneDisplay(
98	            org.springframework.samples.petclinic.util.TelephoneDisplay.format(owner.getTelephone()));
99	    }
100	
101	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
102	
103	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
104	
105	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
106	        OwnerPageDto ownerPageDto = new OwnerPageDto();
107	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
108	        ownerPageDto.setPage(ownerPage.getNumber());
109	        ownerPageDto.setSize(ownerPage.getSize());
110	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
111	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
112	        return ownerPageDto;
113	    }
114	}
