16	package org.springframework.samples.petclinic.mapper;
17	
18	import java.util.Map;
19	
20	/**
21	 * Resolves an owner's locality (region) preferring the postcode: a 4-digit postcode is mapped by
22	 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) first, and only when it is absent or in no
23	 * known range does the fixed city-to-region table decide. Cities that share a name are thereby
24	 * disambiguated by their postcode. Yields 'UNKNOWN' when neither source identifies a region.
25	 */
26	final class LocalityResolver {
27	
28	    /** Fixed city-to-region fallback table. */
29	    private static final Map<String, String> CITY_REGION =
30	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
31	
32	    private LocalityResolver() {
33	    }
34	
35	    static String resolve(String city, String postcode) {
36	        String byPostcode = fromPostcode(postcode);
37	        if (byPostcode != null) {
38	            return byPostcode;
39	        }
40	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
41	    }
42	
43	    private static String fromPostcode(String postcode) {
44	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
45	            return null;
46	        }
47	        return switch (Integer.parseInt(postcode) / 100) {
48	            case 20 -> "NSW";
49	            case 30 -> "VIC";
50	            case 40 -> "QLD";
51	            default -> null;
52	        };
53	    }
54	}
