26	/**
27	 * Rejects an owner whose required text fields are missing or blank. Each offending field is
28	 * reported through the standard validation flow so its name appears in the 400 response.
29	 */
30	@ControllerAdvice
31	public class OwnerFieldsValidationAdvice implements Validator {
32	
33	    @InitBinder
34	    void registerOwnerFieldsValidator(WebDataBinder binder) {
35	        binder.addValidators(this);
36	    }
37	
38	    @Override
39	    public boolean supports(Class<?> clazz) {
40	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
41	    }
42	
43	    @Override
44	    public void validate(Object target, Errors errors) {
45	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
46	        rejectIfBlank(errors, "firstName", owner.getFirstName());
47	        rejectIfBlank(errors, "lastName", owner.getLastName());
48	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
49	        rejectIfBlank(errors, "address", owner.getAddress());
50	        rejectIfBlank(errors, "city", owner.getCity());
51	        rejectIfBlank(errors, "telephone", owner.getTelephone());
52	        normalizeTelephone(errors, owner);
53	    }
54	
55	    private void rejectIfBlank(Errors errors, String field, String value) {
56	        if (value == null || value.isBlank()) {
57	            errors.rejectValue(field, "required", "must not be blank");
58	        }
59	    }
60	
61	    /**
62	     * Normalizes the telephone to E.164 form, storing it back on the payload so it is persisted
63	     * and echoed as-is; rejects the field when no valid E.164 number can be formed.
64	     */
65	    private void normalizeTelephone(Errors errors, OwnerFieldsDto owner) {
66	        if (owner.getTelephone() == null) {
67	            return;
68	        }
69	        String e164 = E164Telephone.toE164(owner.getTelephone());
70	        if (e164 != null) {
71	            owner.setTelephone(e164);
72	        } else {
73	            errors.rejectValue("telephone", "telephone.invalid", "must be a valid E.164 telephone");
74	        }
75	    }
76	}
