23	import java.time.temporal.ChronoUnit;
24	import java.util.Collection;
25	
26	/**
27	 * Scores an owner's membership: points start at 0 and gain +2 for an email, +1 when namesakeCount
28	 * is 0, +2 for a household of 3 or more members and +3 for tenure over 365 days. The points map to a
29	 * membershipLevel of 1 (0-1 points), 2 (2-3), 3 (4-5) or 4 (6 or more). Both are set on the response.
30	 */
31	final class MembershipPoints {
32	
33	    private MembershipPoints() {
34	    }
35	
36	    static void assign(OwnerDto owner, int namesakeCount, Collection<Owner> allOwners) {
37	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
38	        int points = (hasEmail ? 2 : 0) + (namesakeCount == 0 ? 1 : 0)
39	            + (householdSize(owner, allOwners) >= 3 ? 2 : 0) + (longTenure(owner) ? 3 : 0);
40	        owner.setMembershipPoints(points);
41	        owner.setMembershipLevel(points >= 6 ? 4 : points >= 4 ? 3 : points >= 2 ? 2 : 1);
42	    }
43	
44	    /** The number of owners sharing this owner's household (same last name and postcode). */
45	    private static long householdSize(OwnerDto owner, Collection<Owner> allOwners) {
46	        String household = Household.id(owner.getLastName(), owner.getPostcode());
47	        return household == null ? 0 : allOwners.stream()
48	            .filter(o -> household.equals(Household.id(o.getLastName(), o.getPostcode())))
49	            .count();
50	    }
51	
52	    /** True once the owner's tenure exceeds 365 days; a new owner's zero tenure counts as false. */
53	    private static boolean longTenure(OwnerDto owner) {
54	        LocalDate registered = owner.getRegistrationDate();
55	        return registered != null && ChronoUnit.DAYS.between(registered, LocalDate.now()) > 365;
56	    }
57	}
