32	        DayOfWeek day = date.getDayOfWeek();
33	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
34	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
