18	/**
19	 * Formats a stored E.164 telephone for humans: the country code, a space, then the national digits
20	 * grouped in threes (e.g. '+61412345678' -> '+61 412 345 678'). Known country codes '+61' and '+1'
21	 * are split explicitly; any other number keeps a single-digit country code.
22	 */
23	public final class TelephoneDisplay {
24	
25	    private TelephoneDisplay() {
26	    }
27	
28	    public static String format(String e164) {
29	        if (e164 == null) {
30	            return null;
31	        }
32	        String countryCode = e164.startsWith("+61") ? "+61" : e164.startsWith("+1") ? "+1" : e164.substring(0, 2);
33	        String national = e164.substring(countryCode.length());
34	        return countryCode + " " + national.replaceAll("(\\d{3})(?=\\d)", "$1 ");
35	    }
36	}
